use std::borrow::Borrow;
#[cfg(feature = "io")]
use std::io::{self, Read, Write};

/// A munger which XORs a key with some data
#[derive(Clone)]
pub struct Xorcism<'a> {
    key: &'a [u8],
    /// index of the next key byte to be used
    offset: usize,
}

impl<'a> Xorcism<'a> {
    /// Create a new Xorcism munger from a key
    ///
    /// Should accept anything which has a cheap conversion to a byte slice.
    pub fn new<Key: AsRef<[u8]> + ?Sized>(key: &'a Key) -> Xorcism<'a> {
        Xorcism {
            key: key.as_ref(),
            offset: 0,
        }
    }

    /// XOR each byte of the input buffer with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    pub fn munge_in_place(&mut self, data: &mut [u8]) {
        for byte in data {
            *byte ^= self.next_key_byte();
        }
    }

    /// XOR each byte of the data with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    ///
    /// Should accept anything which has a cheap conversion to a byte iterator.
    /// Shouldn't matter whether the byte iterator's values are owned or borrowed.
    pub fn munge<'b, Data: IntoIterator>(
        &'b mut self,
        data: Data,
    ) -> impl Iterator<Item = u8> + 'b + use<'a, 'b, Data>
    where
        Data::Item: Borrow<u8>,
        Data: 'b,
    {
        data.into_iter()
            .map(move |byte| *byte.borrow() ^ self.next_key_byte())
    }

    /// Consume and return the next byte of the (repeating) key.
    fn next_key_byte(&mut self) -> u8 {
        match self.key.get(self.offset) {
            Some(byte) => {
                self.offset = (self.offset + 1) % self.key.len();
                *byte
            }
            // an empty key munges nothing
            None => 0,
        }
    }

    /// Turn this munger into a `Read` adaptor which munges the data read from `reader`.
    #[cfg(feature = "io")]
    pub fn reader<R: Read>(self, reader: R) -> XorcismReader<'a, R> {
        XorcismReader { inner: reader, xs: self }
    }

    /// Turn this munger into a `Write` adaptor which munges the data written to `writer`.
    #[cfg(feature = "io")]
    pub fn writer<W: Write>(self, writer: W) -> XorcismWriter<'a, W> {
        XorcismWriter {
            inner: writer,
            xs: self,
            scratch: [0; 256],
        }
    }
}

