use xorcism::Xorcism;
#[test]
fn borrowed_key_no_copy() {
    let key = String::from("abc");
    let mut xs = Xorcism::new(&key);
    let v: Vec<u8> = xs.munge(vec![1u8, 2, 3, 4, 5]).collect();
    let mut xs2 = Xorcism::new(&key);
    let v2: Vec<u8> = xs2.munge([1u8, 2, 3, 4, 5].iter()).collect();
    assert_eq!(v, v2);
    drop(xs); drop(xs2);
    assert_eq!(&key, "abc");

    let bytes = vec![1u8, 2, 3];
    let mut local = Xorcism::new(&bytes);
    let mut buf = b"hello".to_vec();
    local.munge_in_place(&mut buf);
}
EOF
